                let needs_cleanup = expression.ownership == OwnershipMode::Own
                    && type_needs_drop(program, function, &expression.ty)?;
                if needs_cleanup {
                    let staged_base = temporary_place(base, work)?;
                    for path in &mut paths {
                        if path.failed || path.residual {
                            continue;
                        }
