                        frames,
                        Frame::UpdateField {
                            expression,
                            base,
                            record,
                            fields,
                            index: next,
                            paths,
                            replaced,
                            needs_cleanup,
                        }
                    );
                    push_frame!(frames, Frame::Eval(&fields[next].value));
                } else {
                    produced = Some(finish_update_paths(
                        program,
                        function,
                        expression,
                        base,
                        record,
                        paths,
                        &replaced,
                        needs_cleanup,
                        work,
                    )?);
                }
            }
            Frame::Try { expression } => {
                let operand_paths = produced.take().expect("try operand path retained");
