                    split_boolean_prefixes(condition_paths, &condition.id, work)?;
                if true_prefixes.is_empty() && false_prefixes.is_empty() {
                    produced = Some(results);
                } else if true_prefixes.is_empty() {
                    push_frame!(
                        frames,
                        Frame::IfElse {
                            expression,
                            false_prefixes,
                            results,
                        }
