                expression,
                else_branch,
                true_prefixes,
                false_prefixes,
                mut results,
            } => {
                let then_paths = produced.take().expect("if then path retained");
                let mut selected = sequence_skeleton_paths(true_prefixes, &then_paths, work)?;
