fn require_decided(
    function: &ResolvedFunction,
    factored: &Result<Option<bool>, Diagnostic>,
) {
    assert!(
        !matches!(factored, Ok(None)),
        "funded factored skeleton comparison is undecided for `{}`",
        function.id,
    );
}

